</label>
            </td>

            <td class="text-end">
                {{ formatRate(result.cementBags * buildUpTotal('cement')) }}
            </td>
        </tr>

<tr>
    <td>Sand</td>

    <td class="text-end">
        {{ formatNumber(result.sandKg) }} KG
    </td>

