            <th>Sno</th>
            <th>Cost Center</th>
            <th>Quantity</th>
            <th>Rate</th>
            <th>Cost</th>
            <th></th>
        </tr>
    </thead>

    <tbody>

<tr v-for="item,index in modalData.buildUpRates">
    <td>{{ index + 1 }}</td>
    <td><input type="text" class="form-control" v-model="item.item" placeholder="item"></td>
    <td class="text-end">
        <input type="text" inputmode="decimal" class="form-control" placeholder="Qty"
            :value="formatRateDisplay(item.quantity)"
            @input="handleRateInput($event, item, 'quantity')"
        >
    </td>
    <td class="text-end">
        <input type="text" inputmode="decimal" class="form-control" placeholder="Rate"
            :value="formatRateDisplay(item.rate)"
            @input="handleRateInput($event, item, 'rate')"
        >
    </td>
    <td class="text-end">{{ formatRate(item.quantity * item.rate) }}</td>
    <td class="text-center">
        <button
            class="btn btn-danger btn-sm"
            :disabled="modalData.buildUpRates.length <= 1"
            @click="pullBuildUpRates(index)"
        >
            <i class="bi bi-trash"></i>
        </button>
    </td>
</tr>

    </tbody>

    <tfoot>
        <tr class="table-light">
            <th colspan="5" class="text-end">Total Rate</th>
            <th class="text-end">{{ formatRate(buildUpTotal(modalData.item)) }}</th>
        </tr>
    </tfoot>

</table>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>

      </div>

    </div>
  </div>

</div>
 <!-- ======== RATE MODAL ENDS =========== -->

</template>

<script setup>
import { ref, computed, inject } from 'vue';
import axios from 'axios';
import { useMeta } from '@/composables/use-meta';

useMeta({ title: 'Material Estimates' });
const formatNumber = inject('formatNumber')
const formatRate = inject('formatRate')
const axiosInstance = axios.create({
    baseURL: process.env.VUE_APP_API_BASE_URL
});

const formatRateDisplay = inject('formatRateDisplay')

const selectedClass = ref('');
const wastage = ref(5);
const handleRateInput = inject('handleRateInput')
// Volume input mode: 'dimensions' (L×W×H) or 'cbm' (typed directly)
const inputMode = ref('dimensions');

const length = ref(null);
const width = ref(null);
const height = ref(null);
const manualCbm = ref(null);

// cbm is derived from dimensions when in 'dimensions' mode, or taken
// directly from manualCbm when in 'cbm' mode. The setter lets v-model
// keep working on the CBM input field in either mode.
const cbm = computed({
    get() {
        if (inputMode.value === 'cbm') {
            return manualCbm.value || '';
        }
        return (length.value || 0) * (width.value || 0) * (height.value || 0);
    },
    set(val) {
        manualCbm.value = val;
    }
});


// Exact rates per 1 CBM of concrete, taken directly from the
// "SCHEDULE OF MATERIAL" table in Material_Formula.xls (sheet: CALC, rows 6-10).
// These figures already include the site's standard dry-volume/conversion
// allowance, so no separate shrinkage multiplier is applied on top.
const materialRates = {
    30: { cementBagsPerM3: 10,   sandM3PerM3: 0.5,   aggregateM3PerM3: 1.0  },
    25: { cementBagsPerM3: 7.6,  sandM3PerM3: 0.385, aggregateM3PerM3: 0.82 },
    20: { cementBagsPerM3: 6.08, sandM3PerM3: 0.42,  aggregateM3PerM3: 0.84 },
    15: { cementBagsPerM3: 4.3,  sandM3PerM3: 0.44,  aggregateM3PerM3: 0.88 },
    10: { cementBagsPerM3: 3.36, sandM3PerM3: 0.45,  aggregateM3PerM3: 0.95 }
};

// Material densities (kg/CBM) - used only to express sand/aggregate/cement
// quantities as weight for reference; they do not affect the CBM/bag figures.
const density = {
    cement: 1440,
    sand: 1600,
    aggregate: 1500
};

// Fixed water requirement, in litres per 1 CBM of concrete.
// Applies the same regardless of concrete class.
const WATER_LITERS_PER_M3 = 50;

const totalCost = computed(() => {

    if (!result.value.cementBags) {
        return 0;
    }

    const cementCost = result.value.cementBags * buildUpTotal('cement');
    const sandCost = result.value.sandVolume * buildUpTotal('sand');
    const aggregateCost = result.value.aggregateVolume * buildUpTotal('aggregate');
    const waterCost = result.value.waterVolume * buildUpTotal('water');

    return cementCost + sandCost + aggregateCost + waterCost;

});


const result = computed(() => {

    if (!selectedClass.value || !cbm.value) {
        return {};
    }

    const rate = materialRates[selectedClass.value];

    const adjustmentFactor = 1 + (wastage.value / 100 || 0);

    const adjustedVolume = cbm.value * adjustmentFactor;


    const cementBags =
        adjustedVolume * rate.cementBagsPerM3;

    const sandVolume =
        adjustedVolume * rate.sandM3PerM3;

    const aggregateVolume =
        adjustedVolume * rate.aggregateM3PerM3;

    // Water is a fixed litres-per-CBM figure, same across all classes.
    const waterVolume =
        adjustedVolume * WATER_LITERS_PER_M3;


    const cementKg =
        cementBags * 50; // standard 50kg cement bag

    const sandKg =
        sandVolume * density.sand;

    const aggregateKg =
        aggregateVolume * density.aggregate;


    // Water is excluded from totalKg - it's kept as a separate figure
    // rather than lumped into "dry material" weight.
    const totalKg =
        cementKg + sandKg + aggregateKg;


    return {

        adjustedVolume: adjustedVolume.toFixed(3),

        cementBags: cementBags.toFixed(2),
        cementKg: cementKg.toFixed(2),

        sandVolume: sandVolume.toFixed(3),
        sandKg: sandKg.toFixed(2),

        aggregateVolume: aggregateVolume.toFixed(3),
        aggregateKg: aggregateKg.toFixed(2),

        waterVolume: waterVolume.toFixed(2),

        totalKg: totalKg.toFixed(2)

    };

});

const triggerPrint = (content) => {

    const printWindow = window.open('', '_blank');

    printWindow.document.write(content);

    printWindow.document.close();

    printWindow.focus();

    printWindow.print();

    printWindow.close();

};

const printEstimate = () => {

   const buildUpSections = ['cement', 'sand', 'aggregate', 'water'].map((key) => {

    const rows = buildUpRates.value[key].map((item, index) => `
        <tr>
            <td>${index + 1}</td>
            <td>${item.item || '-'}</td>
            <td class="text-right">${formatNumber(item.quantity || 0)}</td>
            <td class="text-right">${formatRate(item.rate || 0)}</td>
            <td class="text-right">${formatRate((item.quantity || 0) * (item.rate || 0))}</td>
        </tr>
    `).join('');

    return `
        <h4 style="margin-top:20px">${key.toUpperCase()} - Build Up Rate</h4>
        <table>
            <thead>
                <tr>
                    <th>Sno</th>
                    <th>Cost Center</th>
                    <th>Quantity</th>
                    <th>Rate</th>
                    <th>Cost</th>
                </tr>
            </thead>
            <tbody>
                ${rows}
                <tr>
                    <th colspan="4" class="text-right">Total Rate</th>
                    <th class="text-right">${formatRate(buildUpTotal(key))}</th>
                </tr>
            </tbody>
        </table>
    `;

}).join('');

    const materialRows = [
        {
            name: 'Cement',
            quantity: formatNumber(result.value.cementBags) + ' Bags',
            weight: result.value.cementKg,
            rate: buildUpTotal('cement'),
            cost: result.value.cementBags * buildUpTotal('cement')
        },
        {
            name: 'Sand',
            quantity: Number(result.value.sandVolume).toFixed(3) + ' CBM',
            weight: result.value.sandKg,
            rate: buildUpTotal('sand'),
            cost: result.value.sandVolume * buildUpTotal('sand')
        },
        {
            name: 'Aggregate',
            quantity: Number(result.value.aggregateVolume).toFixed(3) + ' CBM',
            weight: result.value.aggregateKg,
            rate: buildUpTotal('aggregate'),
            cost: result.value.aggregateVolume * buildUpTotal('aggregate')
        },
        {
            name: 'Water',
            quantity: Number(result.value.waterVolume).toFixed(2) + ' L',
            weight: result.value.waterVolume,
            rate: buildUpTotal('water'),
            cost: result.value.waterVolume * buildUpTotal('water')
        }
    ];

    const rows = materialRows.map((item, index) => `
        <tr>
            <td>${index + 1}</td>
            <td>${item.name}</td>
            <td class="text-right">${formatNumber(item.weight)} KG</td>
            <td class="text-right">${item.quantity}</td>
            <td class="text-right">${formatRate(item.rate || 0)}</td>
            <td class="text-right">${formatRate(item.cost)}</td>
        </tr>
    `).join('');


    const user = JSON.parse(localStorage.getItem('user'));


    const printContent = `
<!DOCTYPE html>
<html>

<head>

<title>Material Estimate Report</title>

<style>

body {
    font-family: 'Courier New', monospace;
