table {
    width:100%;
    border-collapse:collapse;
    margin-top:15px;
}

th, td {
    border:1px solid #000;
    padding:6px;
}

th {
    background:#f5f5f5;
}

.text-right {
    text-align:right;
}

hr {
    border:0;
    border-top:1px solid #000;
}

