    body {
        margin:10mm;
    }
}

</style>

</head>


<body>


<div class="company-title">

<i>

<h1>COPEX CONTRACTORS CO.LTD</h1>

<div>
<b>Address:</b> Msamvu, P.O.BOX 678, Morogoro
</div>

<div>
<b>Tel:</b> 0713 000 777, 0657 111 555
</div>

<div>
<b>Email:</b> info@copexcontractors.co.tz
</div>

<div>
<b>TIN:</b> 135-489-247
&nbsp;&nbsp;
<b>VRN:</b> 40-032826C
</div>

</i>

</div>


<hr style="margin-top:20px">


<div class="title">
SITE MATERIAL ESTIMATE REPORT
</div>


<hr>


<br>


<table>

<tr>
<th width="30%">
Concrete Class
</th>

<td>
Class ${selectedClass.value}
</td>
</tr>


<tr>
<th>
Concrete Volume
</th>

<td>
${Number(cbm.value).toFixed(3)} CBM
</td>
</tr>


<tr>
<th>
Wastage Factor
</th>

<td>
${wastage.value || 0} %
</td>
</tr>


</table>



<h3>
Material Requirement
</h3>



<table>

<thead>
<tr>
    <th>No.</th>
    <th>Material</th>
    <th>Required Weight (KG)</th>
    <th>Required Quantity</th>
    <th>Rate</th>
    <th>Cost</th>
</tr>
</thead>

<tbody>

${rows}

<tr>
    <th colspan="2">TOTAL</th>
    <th class="text-right">${formatNumber(result.value.totalKg)} KG</th>
    <th class="text-right">-</th>
    <th class="text-right">-</th>
    <th class="text-right">${formatRate(totalCost.value)}</th>
</tr>

<tr>
    <th colspan="2">FINAL CONCRETE VOLUME</th>
    <th class="text-right">-</th>
    <th class="text-right">${Number(cbm.value).toFixed(3)} CBM</th>
    <th class="text-right">-</th>
    <th class="text-right">-</th>
</tr>

</tbody>

</table>


<h3 style="margin-top:20px">
Build Up Rates Summary
</h3>

${buildUpSections}



<div style="margin-top:20px;font-size:10px">


<div style="margin-top:20px;font-size:10px">

<p>
<strong>Generated At:</strong>
${new Date().toLocaleString()}
</p>


<p>
<strong>Generated By:</strong>
${user?.name ?? '---'}
</p>


</div>



</body>

</html>
`;


    triggerPrint(printContent);

};

const buildUpRates = ref({
    cement : [
    { item: 'Loading and Offloading Charges', quantity: '', rate: '50' },
    { item: 'Purchases', quantity: '', rate: '' },
    { item: 'Diesel', quantity: '', rate: '' },
    { item: 'Levy', quantity: '', rate: '' },
    { item: 'Driver Allowance', quantity: '', rate: '' },
    ],
    sand : [
    { item: 'Loading and Offloading Charges', quantity: '', rate: '' },
    { item: 'Purchases', quantity: '', rate: '' },
    { item: 'Diesel', quantity: '', rate: '' },
    { item: 'Levy', quantity: '', rate: '' },
    { item: 'Driver Allowance', quantity: '', rate: '' },
    ],
    aggregate : [ 
    { item: 'Loading and Offloading Charges', quantity: '', rate: '' },
    { item: 'Purchases', quantity: '', rate: '' },
    { item: 'Diesel', quantity: '', rate: '' },
    { item: 'Levy', quantity: '', rate: '' },
    { item: 'Driver Allowance', quantity: '', rate: '' },],
    water : [ 
    { item: 'Water Abstraction Permit', quantity: '', rate: '' },
    { item: 'Diesel', quantity: '', rate: '' },
    { item: 'Driver Allowance', quantity: '', rate: '' },]
})

const modalData = ref({
    item : '',   // 'cement' | 'sand' | 'aggregate' | 'water'
    unit : '',
    buildUpRates : []
})

const fillModal = (key, unit) => {
    modalData.value = {
        item: key,
        unit: unit,
        buildUpRates: buildUpRates.value[key]
    };
};

const pushBuildUpRates = () => {
    const payload = { item: '', quantity: '', rate: '' };
    buildUpRates.value[modalData.value.item].push(payload);
    modalData.value.buildUpRates = buildUpRates.value[modalData.value.item];
};

// Sum(quantity × rate) across all cost-center rows for a given material key.
// This is what feeds the rate column and, downstream, totalCost.
const buildUpTotal = (key) => {
    return (buildUpRates.value[key] || []).reduce(
        (sum, row) => sum + (Number(row.quantity) || 0) * (Number(row.rate) || 0),
        0
    );
};

const pullBuildUpRates = (index) => {
    buildUpRates.value[modalData.value.item].splice(index, 1);
    modalData.value.buildUpRates = buildUpRates.value[modalData.value.item];
};
</script>